discrete EnergyCaptureSystem
port:
    event input real WaveHeight;
    event output real EnergyOutput;
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(WaveHeight) then
            transition(CaptureState);
        end;
    end;

    state CaptureState
        when entry() then
            statehold(30);
        end;
        when timeover() then
            transition(StandbyState);
        end;
        when receive(WaveHeight) then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete EnergyConversionSystem
port:
    event input real EnergyInput;
    event output real PowerOutput;
state:
    initial state InactiveState
        when entry() then
            statehold(0);
        end;
        when receive(EnergyInput) then
            transition(LowEfficiencyState);
        end;
    end;

    state LowEfficiencyState
        when entry() then
            statehold(0);
        end;
        when receive(EnergyInput) then
            transition(HighEfficiencyState);
        end;
    end;

    state HighEfficiencyState
        when entry() then
            statehold(0);
        end;
        when receive(EnergyInput) then
            transition(LowEfficiencyState);
        end;
    end;
end;
end;

discrete PowerTransmissionSystem
port:
    event input real SafetyCheck;
    event input real GridLoad;
    event output real TransmissionStatus;
state:
    initial state DisconnectedState
        when entry() then
            statehold(0);
        end;
        when receive(SafetyCheck) then
            transition(ConnectedButNotTransmittingState);
        end;
    end;

    state ConnectedButNotTransmittingState
        when entry() then
            statehold(0);
        end;
        when receive(GridLoad) then
            transition(NormalTransmissionState);
        end;
    end;

    state NormalTransmissionState
        when entry() then
            statehold(0);
        end;
        when receive(GridLoad) then
            transition(ConnectedButNotTransmittingState);
        end;
        when receive(SafetyCheck) then
            transition(DisconnectedState);
        end;
    end;
end;
end;

couple WaveEnergySystem
import architectureModels.EnergyCaptureSystem as ECS;
